// Standalone prototype only: in-memory records, no real execution or persistence.
const pickerValues={groupPicker:'*',editPicker:''};
const expanded={groupPicker:new Set(groups),editPicker:new Set(groups)};
function updatePicker(id,value){pickerValues[id]=value;const trigger=$(id).querySelector('.tree-trigger');if(trigger){trigger.querySelector('span').textContent=value==='*'?'全部分组':value||'未分组';trigger.title=value||'未分组';drawTree(id)}}
function closePicker(id,focus=false){const el=$(id);el.querySelector('.tree-popup').hidden=true;el.querySelector('.tree-trigger').setAttribute('aria-expanded','false');if(focus)el.querySelector('.tree-trigger').focus()}
function drawTree(id){const el=$(id),query=el.querySelector('input').value.trim().toLowerCase();const matched=groups.filter(g=>g.toLowerCase().includes(query));const visible=groups.filter(g=>query?matched.some(m=>m===g||m.startsWith(g+' / ')):!groups.some(p=>g.startsWith(p+' / ')&&!expanded[id].has(p)));const special=query?[]:(id==='groupPicker'?[['*','全部分组'],['','未分组']]:[['','未分组']]);
function row(g,label,depth,branch){return `<div class="tree-row" style="--depth:${depth}">${branch?`<button type="button" class="tree-toggle" data-expand="${esc(g)}" aria-label="${expanded[id].has(g)||query?'折叠':'展开'} ${esc(label)}" aria-expanded="${!!query||expanded[id].has(g)}" ${query?'disabled':''}>${expanded[id].has(g)||query?'⌄':'›'}</button>`:'<i class="spacer"></i>'}<button type="button" class="tree-choice" data-choice="${esc(g)}" aria-pressed="${pickerValues[id]===g}" title="${esc(g||label)}">${esc(label)}</button></div>`}
el.querySelector('.tree-nodes').innerHTML=special.map(([g,n])=>row(g,n,0,false)).join('')+visible.map(g=>row(g,g.split(' / ').at(-1),g.split(' / ').length-1,groups.some(x=>x.startsWith(g+' / ')))).join('')||'<p class="muted" style="padding:12px">没有匹配分组</p>'}
for(const id of Object.keys(pickerValues)){const el=$(id);el.innerHTML=`<button type="button" class="tree-trigger" aria-label="${id==='groupPicker'?'筛选分组':'配置分组'}" aria-expanded="false" aria-controls="${id}Popup"><span></span>⌄</button><div id="${id}Popup" class="tree-popup" hidden><input type="search" aria-label="检索分组" placeholder="检索分组名称或路径…"><div class="tree-nodes" role="group" aria-label="分组层级"></div></div>`;updatePicker(id,pickerValues[id]);el.querySelector('.tree-trigger').onclick=()=>{const p=el.querySelector('.tree-popup'),open=p.hidden;Object.keys(pickerValues).forEach(k=>closePicker(k));p.hidden=!open;el.querySelector('.tree-trigger').setAttribute('aria-expanded',String(open));if(open){el.querySelector('input').value='';drawTree(id);el.querySelector('input').focus()}};el.querySelector('input').oninput=()=>drawTree(id);el.onclick=e=>{const toggle=e.target.closest('[data-expand]'),choice=e.target.closest('[data-choice]');if(toggle){const g=toggle.dataset.expand;expanded[id].has(g)?expanded[id].delete(g):expanded[id].add(g);drawTree(id);el.querySelectorAll('[data-expand]').forEach(b=>{if(b.dataset.expand===g)b.focus()})}if(choice){updatePicker(id,choice.dataset.choice);if(id==='groupPicker')selectGroup(choice.dataset.choice);closePicker(id,true)}};el.onkeydown=e=>{if(e.key==='Escape'&&!el.querySelector('.tree-popup').hidden){e.preventDefault();e.stopPropagation();closePicker(id,true)}if(['ArrowDown','ArrowUp'].includes(e.key)&&!el.querySelector('.tree-popup').hidden){e.preventDefault();const nodes=[...el.querySelectorAll('.tree-popup input,.tree-popup button:not(:disabled)')];const i=nodes.indexOf(document.activeElement);nodes[(i+(e.key==='ArrowDown'?1:-1)+nodes.length)%nodes.length].focus()}}}
document.addEventListener('pointerdown',e=>{for(const id of Object.keys(pickerValues))if(!$(id).contains(e.target))closePicker(id)});
const records=[
{item:1,source:'快速执行',status:'成功'}, {item:3,source:'脚本库',status:'成功'},
{item:2,source:'网页桥接',status:'成功'}, {item:5,source:'快速执行',status:'失败'},
{item:4,source:'工作流页面',status:'已取消'}, {item:1,source:'工作流页面',status:'成功'}
].map((r,i)=>{const x=items.find(x=>x.id===r.item),startedAt=Date.now()-(i+1)*180000;return{id:'run-demo-'+(i+1),name:x.name,group:x.group,target:{...targets[x.target]},input:JSON.parse(JSON.stringify(x.input)),source:r.source,status:r.status,startedAt,finishedAt:startedAt+2200,output:r.status==='失败'?'请求超时':r.status==='已取消'?'用户取消；已产生的副作用不会撤销。':'{"ok":true,"message":"执行完成"}'}});
let activeRecord=null;
function recordStart(x){const r={id:'run-'+Date.now()+'-'+x.id,name:x.name,group:x.group,target:{...targets[x.target]},input:JSON.parse(JSON.stringify(x.input)),source:'快速执行',status:'运行中',startedAt:Date.now(),finishedAt:null,output:'等待执行结果…'};records.unshift(r);renderHistory();return r}
function renderHistory(){const q=$('historySearch').value.trim().toLowerCase();const out=records.filter(r=>[r.name,r.id,r.target.name].join(' ').toLowerCase().includes(q)&&(!$('historyType').value||r.target.type===$('historyType').value)&&(!$('historySource').value||r.source===$('historySource').value)&&(!$('historyStatus').value||r.status===$('historyStatus').value)).sort((a,b)=>b.startedAt-a.startedAt);$('historyCount').textContent=`${out.length} / ${records.length} 条记录 · 最新在前`;$('historyRows').innerHTML=out.map(r=>`<tr><td title="${esc(r.name)}">${esc(r.name)}<small>${r.id}</small></td><td>${r.target.type}</td><td>${r.source}</td><td class="${r.status==='失败'?'error':''}">${r.status}</td><td>${new Date(r.startedAt).toLocaleString('zh-CN',{hour12:false})}</td><td>${r.finishedAt?((r.finishedAt-r.startedAt)/1000).toFixed(1)+'s':'执行中'}</td><td><button data-record="${r.id}" aria-label="查看 ${r.id}">详情</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">没有匹配的运行记录</td></tr>'}
function showRecord(id,open=true){const r=records.find(r=>r.id===id);if(!r)return;activeRecord=id;$('runBody').innerHTML=`<h2 class="detail-note">${esc(r.name)}</h2><dl><dt>运行 ID</dt><dd>${r.id}</dd><dt>来源</dt><dd>${r.source}</dd><dt>类型 / 目标</dt><dd>${r.target.type} · ${r.target.name} · ${r.target.version}</dd><dt>分组快照</dt><dd>${esc(r.group||'未分组')}</dd><dt>状态</dt><dd>${r.status}</dd><dt>开始时间</dt><dd>${new Date(r.startedAt).toLocaleString('zh-CN')}</dd></dl><h2>本次参数快照</h2><pre>${esc(JSON.stringify(r.input,null,2))}</pre><h2>输出 / 错误</h2><pre>${esc(r.output)}</pre>`;if(open)$('runDetail').showModal()}
$('historyRows').onclick=e=>{const b=e.target.closest('[data-record]');if(b)showRecord(b.dataset.record)};
for(const id of ['historySearch','historyType','historySource','historyStatus'])$(id).oninput=renderHistory;
$('historyClear').onclick=()=>{for(const id of ['historySearch','historyType','historySource','historyStatus'])$(id).value='';renderHistory()};
function route(){const history=location.hash==='#history';$('launchPage').classList.toggle('hidden',history);$('historyPage').classList.toggle('hidden',!history);$('pageTitle').textContent=history?'运行记录':'快速执行';$('pageSubtitle').textContent=history?'工作流、脚本与浏览器工具的统一执行历史':'固定参数，一键启动';$('create').classList.toggle('hidden',history);document.querySelectorAll('[data-page]').forEach(a=>{const current=a.dataset.page===(history?'history':'launch');a.classList.toggle('active',current);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});renderHistory()}
window.addEventListener('hashchange',route);route();
